import java.util.ArrayList;
import java.util.concurrent.*;

public class VirtualThreadDemo {
 public static void main(String[] args) throws Exception {
  var permits = new Semaphore(4); // simulated downstream capacity
  var results = new ArrayList<Future<String>>();
  try (var executor = Executors.newVirtualThreadPerTaskExecutor()) {
   for (int i = 0; i < 12; i++) {
    final int id = i;
    results.add(executor.submit(() -> {
     if (!permits.tryAcquire(1, TimeUnit.SECONDS))
      throw new TimeoutException("Downstream busy");
     try {
      Thread.sleep(20); // simulate waiting for I/O; no network needed
      return id + ": virtual=" + Thread.currentThread().isVirtual();
     } finally { permits.release(); }
    }));
   }
   try {
    for (var result : results) System.out.println(result.get(2, TimeUnit.SECONDS));
   } catch (InterruptedException e) {
    results.forEach(f -> f.cancel(true));
    Thread.currentThread().interrupt();
    throw e;
   } catch (ExecutionException | TimeoutException e) {
    results.forEach(f -> f.cancel(true));
    throw e;
   }
  } // close waits for tasks to finish
 }
}

import java.util.*;
import java.util.concurrent.*;

public class ParkingLotDemo {
 enum Kind {BIKE,CAR,TRUCK}
 enum Direction {ENTRY,EXIT}
 record Gate(String id,int level,Direction direction){}
 record Slot(String id,int level,Kind kind){}
 record Vehicle(String plate,Kind kind){}
 record Ticket(long id,Vehicle vehicle,Slot slot,String entryGate){}
 static class Lot {
  private final Map<String,Gate> gates=new HashMap<>();
  private final Map<String,Slot> free=new HashMap<>();
  private final Map<Long,Ticket> active=new HashMap<>();
  private final Set<String> parked=new HashSet<>();
  private long nextId=1;
  Lot(List<Gate> gates,List<Slot> slots){
   for(Gate g:gates)if(this.gates.putIfAbsent(g.id(),g)!=null)throw new IllegalArgumentException("duplicate gate");
   for(Slot s:slots)if(free.putIfAbsent(s.id(),s)!=null)throw new IllegalArgumentException("duplicate slot");
  }
  private Gate gate(String id,Direction direction){
   Gate g=gates.get(id);if(g==null||g.direction()!=direction)throw new IllegalArgumentException("invalid gate");return g;
  }
  synchronized Optional<Ticket> enter(String gateId,Vehicle vehicle){
   Gate entry=gate(gateId,Direction.ENTRY);Objects.requireNonNull(vehicle);
   if(vehicle.plate()==null||vehicle.plate().isBlank()||vehicle.kind()==null)throw new IllegalArgumentException("vehicle required");
   if(parked.contains(vehicle.plate()))throw new IllegalStateException("already parked");
   // Explicit policy: exact kind, nearest level to gate, then stable slot ID.
   Optional<Slot> candidate=free.values().stream().filter(s->s.kind()==vehicle.kind())
    .min(Comparator.<Slot>comparingLong(s->Math.abs((long)s.level()-entry.level())).thenComparing(Slot::id));
   if(candidate.isEmpty())return Optional.empty();
   Slot slot=candidate.get();Ticket ticket=new Ticket(nextId++,vehicle,slot,gateId);
   free.remove(slot.id());parked.add(vehicle.plate());active.put(ticket.id(),ticket);return Optional.of(ticket);
  }
  synchronized Ticket exit(String gateId,long ticketId){
   gate(gateId,Direction.EXIT);Ticket ticket=active.get(ticketId);
   if(ticket==null)throw new IllegalArgumentException("unknown or closed ticket");
   active.remove(ticketId);parked.remove(ticket.vehicle().plate());free.put(ticket.slot().id(),ticket.slot());return ticket;
  }
 }
 static void check(boolean value){if(!value)throw new AssertionError();}
 public static void main(String[] args)throws Exception{
  var gates=List.of(new Gate("E0",0,Direction.ENTRY),new Gate("E1",1,Direction.ENTRY),new Gate("X0",0,Direction.EXIT));
  Lot lot=new Lot(gates,List.of(new Slot("L0-C1",0,Kind.CAR),new Slot("L1-C1",1,Kind.CAR),new Slot("L0-B1",0,Kind.BIKE)));
  Ticket ticket=lot.enter("E1",new Vehicle("CAR-81",Kind.CAR)).orElseThrow();check(ticket.slot().level()==1);
  try{lot.enter("E0",ticket.vehicle());throw new AssertionError();}catch(IllegalStateException expected){}
  try{lot.exit("E0",ticket.id());throw new AssertionError();}catch(IllegalArgumentException expected){}
  check(lot.exit("X0",ticket.id()).equals(ticket));
  try{lot.exit("X0",ticket.id());throw new AssertionError();}catch(IllegalArgumentException expected){}
  Lot one=new Lot(gates,List.of(new Slot("only",0,Kind.CAR)));
  try(var pool=Executors.newFixedThreadPool(2)){
   var a=pool.submit(()->one.enter("E0",new Vehicle("A",Kind.CAR)).isPresent());
   var b=pool.submit(()->one.enter("E1",new Vehicle("B",Kind.CAR)).isPresent());
   check((a.get()?1:0)+(b.get()?1:0)==1);
  }
  System.out.println("PASS: levels, gate validation, exact-kind policy, closed tickets and competing entries");
 }
}

import java.util.*;
public class TicTacToeDemo {
 enum Mark {X,O}
 enum State {IN_PROGRESS,X_WON,O_WON,DRAW}
 static class Game {
  private final Mark[][] board=new Mark[3][3];private Mark turn=Mark.X;private State state=State.IN_PROGRESS;private int moves;
  synchronized State move(Mark player,int row,int col){
   Objects.requireNonNull(player);
   if(state!=State.IN_PROGRESS)throw new IllegalStateException("game over");
   if(player!=turn)throw new IllegalArgumentException("wrong turn");
   if(row<0||row>=3||col<0||col>=3||board[row][col]!=null)throw new IllegalArgumentException("invalid cell");
   board[row][col]=player;moves++;
   boolean rowWin=true,colWin=true,diag=true,anti=true;
   for(int i=0;i<3;i++){rowWin&=board[row][i]==player;colWin&=board[i][col]==player;diag&=board[i][i]==player;anti&=board[i][2-i]==player;}
   if(rowWin||colWin||diag||anti)state=player==Mark.X?State.X_WON:State.O_WON;
   else if(moves==9)state=State.DRAW;else turn=turn==Mark.X?Mark.O:Mark.X;
   return state;
  }
 }
 static void check(boolean ok){if(!ok)throw new AssertionError();}
 public static void main(String[] args){
  Game win=new Game();
  try{win.move(Mark.O,0,0);throw new AssertionError();}catch(IllegalArgumentException expected){}
  win.move(Mark.X,0,0);
  try{win.move(Mark.O,0,0);throw new AssertionError();}catch(IllegalArgumentException expected){}
  win.move(Mark.O,1,0);win.move(Mark.X,0,1);win.move(Mark.O,1,1);check(win.move(Mark.X,0,2)==State.X_WON);
  try{win.move(Mark.O,2,2);throw new AssertionError();}catch(IllegalStateException expected){}
  Game draw=new Game();int[][] cells={{0,0},{0,1},{0,2},{1,1},{1,0},{1,2},{2,1},{2,0},{2,2}};
  State result=null;for(int i=0;i<cells.length;i++)result=draw.move(i%2==0?Mark.X:Mark.O,cells[i][0],cells[i][1]);check(result==State.DRAW);
  Game diagonal=new Game();diagonal.move(Mark.X,0,0);diagonal.move(Mark.O,0,1);diagonal.move(Mark.X,1,1);diagonal.move(Mark.O,0,2);check(diagonal.move(Mark.X,2,2)==State.X_WON);
  try{new Game().move(Mark.X,-1,0);throw new AssertionError();}catch(IllegalArgumentException expected){}
  System.out.println("PASS: turn, occupied/out-of-range cells, row/diagonal wins, draw and terminal state");
 }
}

import java.util.*;
public class LruCacheDemo {
 static class Lru<K,V> {
  private static class Node<K,V>{K key;V value;Node<K,V> prev,next;Node(K k,V v){key=k;value=v;}}
  private final int capacity;private final Map<K,Node<K,V>> index=new HashMap<>();
  private final Node<K,V> head=new Node<>(null,null),tail=new Node<>(null,null);
  Lru(int capacity){if(capacity<0)throw new IllegalArgumentException();this.capacity=capacity;head.next=tail;tail.prev=head;}
  private void detach(Node<K,V> n){n.prev.next=n.next;n.next.prev=n.prev;}
  private void newest(Node<K,V> n){n.next=head.next;n.prev=head;head.next.prev=n;head.next=n;}
  synchronized Optional<V> get(K key){Objects.requireNonNull(key);Node<K,V> n=index.get(key);if(n==null)return Optional.empty();detach(n);newest(n);return Optional.of(n.value);}
  synchronized void put(K key,V value){Objects.requireNonNull(key);Objects.requireNonNull(value);
   Node<K,V> n=index.get(key);if(n!=null){n.value=value;detach(n);newest(n);return;}
   if(capacity==0)return;n=new Node<>(key,value);index.put(key,n);newest(n);
   if(index.size()>capacity){Node<K,V> old=tail.prev;detach(old);index.remove(old.key);}
  }
  synchronized void verify(){
   int count=0;Node<K,V> previous=head;
   for(Node<K,V> n=head.next;n!=tail;n=n.next){if(n.prev!=previous||index.get(n.key)!=n)throw new AssertionError();previous=n;if(++count>index.size())throw new AssertionError("cycle");}
   if(tail.prev!=previous||count!=index.size()||count>capacity)throw new AssertionError();
  }
 }
 static void check(boolean ok){if(!ok)throw new AssertionError();}
 public static void main(String[] args){
  Lru<Integer,String> cache=new Lru<>(2);cache.put(1,"A");cache.put(2,"B");cache.get(1);cache.put(3,"C");
  check(cache.get(2).isEmpty());check(cache.get(1).orElseThrow().equals("A"));cache.verify();
  cache.put(1,"A2");cache.put(4,"D");check(cache.get(3).isEmpty());check(cache.get(1).orElseThrow().equals("A2"));cache.verify();
  Lru<Integer,String> zero=new Lru<>(0);zero.put(1,"X");check(zero.get(1).isEmpty());zero.verify();
  Random random=new Random(81);Lru<Integer,Integer> actual=new Lru<>(5);
  LinkedHashMap<Integer,Integer> model=new LinkedHashMap<>(16,.75f,true);
  for(int i=0;i<1000;i++){
   int key=random.nextInt(12);
   if(random.nextBoolean()){int v=random.nextInt(100);actual.put(key,v);model.put(key,v);if(model.size()>5)model.remove(model.keySet().iterator().next());}
   else check(actual.get(key).equals(Optional.ofNullable(model.get(key))));
   actual.verify();
  }
  System.out.println("PASS: access/update recency, eviction, zero capacity, list invariants and reference-model comparison");
 }
}

import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.locks.*;
import java.util.function.BiFunction;
public class StripedMapDemo {
 static class Bucket<K,V>{final Map<K,V> values=new HashMap<>();final ReadWriteLock lock=new ReentrantReadWriteLock();}
 // Fixed stripes; not ConcurrentHashMap's implementation or performance contract.
 static class StripedMap<K,V>{
  private final List<Bucket<K,V>> buckets;
  StripedMap(int stripes){if(stripes<1)throw new IllegalArgumentException();buckets=new ArrayList<>();for(int i=0;i<stripes;i++)buckets.add(new Bucket<>());}
  private Bucket<K,V> bucket(K key){Objects.requireNonNull(key);return buckets.get(Math.floorMod(key.hashCode(),buckets.size()));}
  V get(K key){var b=bucket(key);b.lock.readLock().lock();try{return b.values.get(key);}finally{b.lock.readLock().unlock();}}
  void put(K key,V value){Objects.requireNonNull(value);var b=bucket(key);b.lock.writeLock().lock();try{b.values.put(key,value);}finally{b.lock.writeLock().unlock();}}
  V compute(K key,BiFunction<K,V,V> change){Objects.requireNonNull(change);var b=bucket(key);b.lock.writeLock().lock();try{
   V next=change.apply(key,b.values.get(key));if(next==null)b.values.remove(key);else b.values.put(key,next);return next;
  }finally{b.lock.writeLock().unlock();}}
  // Callbacks must not invoke this map (including snapshot) or block on external work.
  Map<K,V> snapshot(){for(var b:buckets)b.lock.readLock().lock();try{
   Map<K,V> copy=new HashMap<>();for(var b:buckets)copy.putAll(b.values);return Map.copyOf(copy);
  }finally{for(int i=buckets.size()-1;i>=0;i--)buckets.get(i).lock.readLock().unlock();}}
 }
 record Collision(String key){public int hashCode(){return Integer.MIN_VALUE;}}
 public static void main(String[] args)throws Exception{
  var map=new StripedMap<String,Integer>(8);map.put("count",0);
  try(var pool=Executors.newFixedThreadPool(8)){
   List<Future<?>> work=new ArrayList<>();for(int t=0;t<8;t++)work.add(pool.submit(()->{for(int i=0;i<1000;i++)map.compute("count",(k,v)->v+1);}));
   for(var f:work)f.get();
  }
  if(map.get("count")!=8000||map.snapshot().get("count")!=8000)throw new AssertionError();
  map.compute("count",(k,v)->null);if(map.get("count")!=null)throw new AssertionError();
  var collisions=new StripedMap<Collision,Integer>(3);collisions.put(new Collision("A"),1);collisions.put(new Collision("B"),2);
  if(collisions.get(new Collision("A"))!=1||collisions.get(new Collision("B"))!=2)throw new AssertionError();
  try{map.put("bad",null);throw new AssertionError();}catch(NullPointerException expected){}
  System.out.println("PASS: atomic increments, collision equality, MIN_VALUE hash, removal and consistent snapshot");
 }
}

import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import java.util.function.LongSupplier;
public class TokenBucketDemo {
 static class Bucket {
  private final double capacity,perSecond;private final LongSupplier clock;private double tokens;private long last;
  Bucket(int capacity,double perSecond,LongSupplier clock){
   if(capacity<1||!Double.isFinite(perSecond)||perSecond<=0)throw new IllegalArgumentException();
   this.capacity=capacity;this.perSecond=perSecond;this.clock=Objects.requireNonNull(clock);tokens=capacity;last=clock.getAsLong();
  }
  synchronized boolean allow(int cost){
   if(cost<1)throw new IllegalArgumentException("positive cost required");long now=clock.getAsLong();long elapsed=now-last;
   if(elapsed>0){tokens=Math.min(capacity,tokens+elapsed/1_000_000_000.0*perSecond);last=now;}
   if(tokens<cost)return false;tokens-=cost;return true;
  }
 }
 // A fixed authenticated-tenant registry avoids unbounded attacker-created keys in this demo.
 record Limiter(Map<String,Bucket> configured){
  Limiter{configured=Map.copyOf(configured);}
  boolean allow(String trustedTenant,int cost){Bucket b=configured.get(trustedTenant);if(b==null)throw new IllegalArgumentException("unknown tenant");return b.allow(cost);}
 }
 static void check(boolean ok){if(!ok)throw new AssertionError();}
 public static void main(String[] args)throws Exception{
  AtomicLong time=new AtomicLong();Bucket b=new Bucket(2,1,time::get);check(b.allow(1));check(b.allow(1));check(!b.allow(1));
  time.addAndGet(500_000_000);check(!b.allow(1));time.addAndGet(500_000_000);check(b.allow(1));check(!b.allow(1));
  Bucket racing=new Bucket(10,1,time::get);AtomicInteger accepted=new AtomicInteger();
  try(var pool=Executors.newFixedThreadPool(8)){
   List<Future<?>> work=new ArrayList<>();for(int i=0;i<50;i++)work.add(pool.submit(()->{if(racing.allow(1))accepted.incrementAndGet();}));for(var f:work)f.get();
  }
  check(accepted.get()==10);
  Limiter limiter=new Limiter(Map.of("A",new Bucket(1,1,time::get),"B",new Bucket(1,1,time::get)));
  check(limiter.allow("A",1));check(!limiter.allow("A",1));check(limiter.allow("B",1));
  try{b.allow(0);throw new AssertionError();}catch(IllegalArgumentException expected){}
  System.out.println("PASS: burst/refill without sleeps, final-token concurrency, independent tenants and invalid cost");
 }
}

